def(462, 'Remiendo', 'gnomo', 'comun', { cost: c(2), s: s({ wall: 5 }), text: 'Muro +5; presión −2', plusText: 'Muro +7; presión −2', plus: { s: s({ wall: 7 }) }, camp: { pressure: -2 } });
